    ["<Assistant_Title1>【Club - Club Activity Allowance】</>\n<Assistant_Title2>System Access: </><Assistant_System>Menu - Club - Benefits - Activity Allowance</>{JumpToUI:[【View】]|1250320}\n<Assistant_Title2>Gameplay Description: </>Complete activity allowance quests to earn Peer Emblems, Club activity, and Club fund rewards.\nClub activity is the sum of individual activity values of current Club members; reaching corresponding values allows you to claim extra rewards.\nActivity allowance rewards will refresh every Monday at 8:00; please claim your rewards in time.\n<Assistant_Title3>Recommended Searches: </>{SendAnswer:[Club]|1400}, {SendAnswer:[Club-Club Dividends]|1405}, {SendAnswer:[Club-Club Activity]|1403}"] = "<Assistant_Title1>【Клуб - Пособие по активности в клубе】</>\n<Assistant_Title2>Доступ к системе: </><Assistant_System>Меню - Клуб - Преимущества - Пособие по активности</>{JumpToUI:[【Перейти к просмотру】|1250320}\n<Assistant_Title2>Описание игрового процесса: </>Выполняйте квесты по разрешению активности, чтобы заработать эмблемы сверстников, Клуб активность и вознаграждения из фонда Клуба.\nАктивность Клуба представляет собой сумму индивидуальных показателей активности текущих членов Клуба; достижение соответствующих значений позволяет вам претендовать на дополнительные награды.\nНаграды за активность будут обновляться каждый понедельник в 8:00; пожалуйста, получите вознаграждение вовремя.\n<Assistant_Title3>Рекомендуемые поисковые запросы: </>{SendAnswer:[CLUB]|1400}, {SendAnswer:[Club-Club Dividend]|1405}, {SendAnswer:[Club-Club Active]|1403}",
